import type { ApprovalRequest } from "../core/tools.ts";
import { theme } from "../theme.ts";

interface ApprovalProps {
  request: ApprovalRequest;
  onDecision: (approved: boolean, always: boolean) => void;
}

export function Approval({ request, onDecision }: ApprovalProps): React.ReactElement {
  useInput((input, key) => {
    if (input === "y" || key.return) onDecision(true, false);
    else if (input === "a") onDecision(true, true);
    else if (input === "n" || key.escape) onDecision(false, false);
