    const ws = new WebSocket('ws://localhost:3001/ws', { headers: { Cookie: cookie } });
    ws.inbox = [];
    ws.waiters = [];
    ws.on('message', (raw) => {
      const msg = JSON.parse(raw);
      const w = ws.waiters.find((x) => x.t === msg.t);
      if (w) { ws.waiters.splice(ws.waiters.indexOf(w), 1); w.resolve(msg); }
      else ws.inbox.push(msg);
    });
    ws.on('open', () => resolve(ws));
    ws.on('error', reject);
  });
}

function expect(ws, t, timeout = 4000) {
  const found = ws.inbox.find((m) => m.t === t);
  if (found) { ws.inbox.splice(ws.inbox.indexOf(found), 1); return Promise.resolve(found); }
  return new Promise((resolve, reject) => {
    const w = { t, resolve };
    ws.waiters.push(w);
    setTimeout(() => reject(new Error('timeout waiting for ' + t)), timeout);
  });
}

