import { buildSoldier, makeNameTag } from './soldier.js';

const EYE = 1.55;

class Avatar {
  constructor(scene, kind) {
    this.scene = scene;
    this.group = new THREE.Group();
    this.parts = buildSoldier(this.group, kind);
    this.alive = true;
    this.deathT = 0;
    scene.add(this.group);
  }

  setDead() {
    if (!this.alive) return;
    this.alive = false;
    this.deathT = 0;
  }

  revive(x, z) {
    this.alive = true;
    this.deathT = 0;
    this.group.rotation.z = 0;
    this.group.position.set(x, 0, z);
    this.group.scale.set(1, 1, 1);
  }

  tickDeath(dt) {
    this.deathT = Math.min(1, this.deathT + dt * 2.6);
    const t = this.deathT;
    this.group.rotation.z = (Math.PI / 2) * t * t;
    this.group.position.y = -0.15 * t;
  }

  animateLegs(time, rate) {
    const swing = Math.sin(time * rate) * 0.3;
    this.parts.legL.rotation.x = swing;
    this.parts.legR.rotation.x = -swing;
  }

  dispose() {
    this.scene.remove(this.group);
  }
}

