function makeCanvas(size, draw) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  draw(c.getContext('2d'), size);
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

function speckle(g, s, count, alpha, dark) {
  for (let i = 0; i < count; i++) {
    const v = dark ? Math.random() * 60 : 160 + Math.random() * 60;
    g.fillStyle = `rgba(${v},${v},${v},${alpha})`;
    g.fillRect(Math.random() * s, Math.random() * s, 1 + Math.random() * 2, 1 + Math.random() * 2);
  }
}

function concreteTexture() {
  return makeCanvas(512, (g, s) => {
    g.fillStyle = '#8d8a84';
    g.fillRect(0, 0, s, s);
    speckle(g, s, 9000, 0.10, true);
    speckle(g, s, 6000, 0.08, false);
    // stains
    for (let i = 0; i < 12; i++) {
      const grad = g.createRadialGradient(
        Math.random() * s, Math.random() * s, 4,
        Math.random() * s, Math.random() * s, 50 + Math.random() * 90);
      grad.addColorStop(0, 'rgba(40,38,34,0.13)');
      grad.addColorStop(1, 'rgba(40,38,34,0)');
      g.fillStyle = grad;
      g.fillRect(0, 0, s, s);
    }
    // expansion joints
    g.strokeStyle = 'rgba(30,30,30,0.5)';
    g.lineWidth = 3;
    g.strokeRect(1, 1, s - 2, s - 2);
  });
}

function plasterTexture() {
  return makeCanvas(512, (g, s) => {
    g.fillStyle = '#a6a29a';
    g.fillRect(0, 0, s, s);
    speckle(g, s, 7000, 0.07, true);
    speckle(g, s, 5000, 0.06, false);
    // grime streaks running down
    for (let i = 0; i < 26; i++) {
      const x = Math.random() * s;
      const grad = g.createLinearGradient(x, 0, x, s);
      grad.addColorStop(0, 'rgba(60,55,48,0)');
      grad.addColorStop(1, `rgba(60,55,48,${0.04 + Math.random() * 0.10})`);
      g.fillStyle = grad;
      g.fillRect(x, 0, 3 + Math.random() * 14, s);
    }
    // scuffs near "floor" edge
    g.fillStyle = 'rgba(48,44,40,0.25)';
    for (let i = 0; i < 40; i++) {
      g.fillRect(Math.random() * s, s - 40 + Math.random() * 40, 4 + Math.random() * 20, 2 + Math.random() * 4);
    }
  });
}

function plywoodTexture() {
  return makeCanvas(256, (g, s) => {
    g.fillStyle = '#9a7748';
    g.fillRect(0, 0, s, s);
    // grain
    for (let i = 0; i < 90; i++) {
      g.strokeStyle = `rgba(${60 + Math.random() * 40},${42 + Math.random() * 26},20,${0.10 + Math.random() * 0.18})`;
      g.lineWidth = 1 + Math.random() * 2;
      g.beginPath();
